import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Plane with texture ---
  const geometry = new PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.ink ?? '#16161d',
      align: 'left',
    });
    // Slightly offset to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  }

  // --- Cinematic primitives ---
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](group, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // --- Interaction handlers ---
  const handlers = {};

  // Hover lift (rise‑in)
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(group.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });
  handlers.hover = () => {
    hoverTL.restart();
  };

  // Click press‑down + emit navigation
  const clickTL = gsap.timeline({ paused: true });
  clickTL.to(group.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  });
  handlers.click = () => {
    clickTL.restart();
    ctx.emit('hub-journal.select', {});
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Dispose material & geometry
    material.dispose();
    geometry.dispose();

    // Kill GSAP timelines
    hoverTL.kill();
    clickTL.kill();

    // Cleanup primitives
    for (const p of primitiveInstances) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Dispose any child meshes/texts that may hold resources
    group.traverse((child) => {
      if (child !== group) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return group;
}
